(() => {
  const root = document.getElementById('powhatan-learning-room');
  const get = name => root.querySelector('.pq-' + name);
  const frame = window.frameElement;
  if (frame && frame.classList.contains('study-quiz-frame')) {
    document.body.classList.add('inside-learning-room');
    const sizeFrame = () => { frame.style.height = Math.ceil(root.getBoundingClientRect().height) + 'px'; };
    new ResizeObserver(sizeFrame).observe(root);
    sizeFrame();
  }
  const questions = [{"chapter": "The English arrive", "art": "ships", "q": "Which people used the Jamestown site for seasonal hunting and fishing before the English built there in 1607?", "a": ["The Monacan", "The Paspahegh", "The people of Kecoughtan"], "key": 1, "why": "The Paspahegh used the site seasonally. Their towns stood a few miles away. The English could build there without displacing a village and still be settling on someone else’s land."}, {"chapter": "The English arrive", "art": "ships", "q": "Why did the English choose that marshy peninsula?", "a": ["Its fields had already been cleared and planted.", "Its shallow water would keep every large ship offshore.", "Their ships could anchor close, and the inland site was easier to defend."], "key": 2, "why": "The river was deep right beside the shore. Callan explains that the English also had a possible Spanish attack in mind."}, {"chapter": "The first welcome", "art": "welcome", "q": "At Cape Comfort, what did Captain Newport do just before the people onshore lowered their bows?", "a": ["Placed his hand over his heart.", "Offered them his hat.", "Set a grindstone on the shore."], "key": 0, "why": "Newport put his hand over his heart. The people onshore invited the visitors to Kecoughtan, where they fed them. The English gave gifts."}, {"chapter": "The first welcome", "art": "fort", "q": "The Paspahegh welcomed English visitors at first. What did the newcomers do that raised tensions?", "a": ["Began building a fort on Paspahegh land.", "Stopped at Kecoughtan for a meal.", "Anchored long enough to exchange gifts."], "key": 0, "why": "A visit became a settlement. Within weeks, Paspahegh warriors and others attacked the fort."}, {"chapter": "Making peace", "art": "fort", "q": "How did Powhatan persuade local chiefs to honor his June 1607 peace offer?", "a": ["He promised the English would leave after the harvest.", "He gave the chiefs control of trade at Jamestown.", "He warned that he would side with the English if the attacks continued."], "key": 2, "why": "Powhatan sent word that the settlers could plant and harvest in peace. Jamestown’s president recorded that the chiefs kept the peace and traded with the English."}, {"chapter": "Trade and alliances", "art": "trade", "q": "Which western rival did Powhatan discuss when Shane asked why the English might make useful allies?", "a": ["The Paspahegh", "The Monacan", "The people of Kecoughtan"], "key": 1, "why": "Powhatan describes raids between his people and the Monacan. In the show’s telling, he saw advantages in English tools and weapons and wanted to keep the newcomers from siding with his rivals."}, {"chapter": "Trade and alliances", "art": "autumn", "q": "When sickness and hunger struck Jamestown that autumn, where did food that helped the settlers survive come from?", "a": ["Nearby Native communities", "An English supply fleet that arrived in autumn", "Spanish settlements along the coast"], "key": 0, "why": "Callan credits food supplied by nearby Native communities. That dependence helps explain why trade in corn mattered so much in the negotiations that followed."}, {"chapter": "Smith goes upriver", "art": "smith", "q": "Whose men captured John Smith while he was exploring the Chickahominy River?", "a": ["Christopher Newport’s", "John Rolfe’s", "Opechancanough’s"], "key": 2, "why": "Opechancanough was Powhatan’s brother. Smith was taken through several towns before reaching Powhatan at Werowocomoco."}, {"chapter": "An offer to Smith", "art": "smith", "q": "In Smith’s later account, what place did Powhatan offer him in his family?", "a": ["A brother", "A son", "A son-in-law"], "key": 1, "why": "Smith later wrote that Powhatan offered to make him a son. The episode interprets that offer, along with land at Capahosic, as a way to bring the English into Powhatan’s alliance."}, {"chapter": "An offer to Smith", "art": "smith", "q": "What two things did Powhatan ask Smith to supply?", "a": ["A crown and a greyhound", "A canoe and a cargo of corn", "Two cannons and a grindstone"], "key": 2, "why": "The grindstone was for sharpening tools. Smith offered the cannons, but they were too heavy for Powhatan’s men to carry. The English stayed at Jamestown."}, {"chapter": "England’s plans", "art": "ships", "q": "Besides authorizing a colony, what did King James’s charter call for?", "a": ["Spreading Christianity among the Native peoples", "Moving the English settlement to Capahosic", "Giving Powhatan authority over English settlers"], "key": 0, "why": "The charter set out that religious aim before the settlers sailed. Powhatan’s reply draws attention to his people’s own priests, beliefs, and sacred places."}, {"chapter": "Newport’s visit", "art": "trade", "q": "When Smith and Newport visited Powhatan in February 1608, what came with the clothing and hat?", "a": ["A crown", "A greyhound", "A grindstone"], "key": 1, "why": "They brought a greyhound. A fire had destroyed much of Jamestown’s food and shelter, and the visitors needed corn. Powhatan welcomed and fed them.", "revealArt": "dog"}, {"chapter": "A strained bargain", "art": "trade", "q": "Powhatan gives two reasons the relationship began to sour. Which pair does he name?", "a": ["A missing greyhound and a demand for another gift", "A dispute over the harvest and a Spanish attack", "Promised tools that failed to arrive and English exploration farther afield"], "key": 2, "why": "Food had already been supplied. Some of the tools promised in return never came, and the English explored beyond the area where Powhatan expected them to stay."}, {"chapter": "The crown", "art": "crown", "q": "The English brought King James’s crown to Werowocomoco. What did Powhatan refuse to do?", "a": ["Kneel for the ceremony.", "Meet Newport at his capital.", "Let Newport bring the crown there."], "key": 0, "why": "Smith wrote that the English pressed on Powhatan’s shoulders so Newport could place the crown on his head. In the episode, Powhatan makes clear that he never agreed to serve King James."}, {"chapter": "Friend or subject?", "art": "smith", "q": "Smith still called Powhatan “father” in 1609. According to Smith’s account, how did he describe their relationship?", "a": ["He owed obedience to both Powhatan and King James.", "He was Powhatan’s friend and owed allegiance to King James.", "He would become Powhatan’s subject once the English moved."], "key": 1, "why": "Smith said he honored only one king. Calling Powhatan “father” still left the two men at odds over who had the right to rule."}, {"chapter": "From trade to war", "art": "autumn", "q": "As relations broke down, how did the struggle over corn change?", "a": ["Smith used threats and force, and Powhatan tried to cut off supplies.", "Smith abandoned the corn trade, and Jamestown lived on food from England.", "Powhatan increased deliveries, and Smith moved the settlers to Capahosic."], "key": 0, "why": "Each side used the settlers’ dependence on corn to press its case. Open war followed in 1609."}, {"chapter": "Pocahontas and the peace", "art": "studio", "q": "After the English took Pocahontas hostage in 1613, what helped secure peace the following year?", "a": ["John Smith’s return to Werowocomoco", "The English withdrawal from Jamestown", "Her marriage to John Rolfe"], "key": 2, "why": "Pocahontas married John Rolfe in 1614. Callan closes this part of the story by noting that English settlements continued to spread during the peace.", "revealArt": "pocahontas"}, {"chapter": "After Powhatan", "art": "studio", "q": "Shane closes the episode by naming two brothers of Powhatan. Which one organized the attacks of 1622?", "a": ["Opitchapam", "Opechancanough", "Neither; Powhatan was still leading in 1622."], "key": 1, "why": "Opitchapam succeeded Powhatan after his death in 1618. Opechancanough gained power and organized the 1622 attacks, which began another war."}];
  const illustrations = {"ships": "powhatan-ships.jpg", "welcome": "powhatan-welcome.jpg", "fort": "powhatan-fort.jpg", "trade": "powhatan-trade.jpg", "autumn": "powhatan-autumn.jpg", "smith": "powhatan-smith.jpg", "dog": "powhatan-dog.jpg", "crown": "powhatan-crown.jpg", "pocahontas": "powhatan-pocahontas.jpg"};
  const soundBytes = '';
  const soundButton = get('sound');
  const next = get('next');
  const feedback = get('feedback');
  let position = 0, firstTry = 0, missed = false, answered = false, muted = false;
  let context, jingle, playing;
  let soundGeneration = 0;
  function stopSound() {
    soundGeneration++;
    if (playing) { try { playing.stop(); } catch {} playing = null; }
  }
  function readyAudio() {
    if (muted) return;
    try {
      const AudioEngine = window.AudioContext || window.webkitAudioContext;
      if (!AudioEngine) return;
      if (!context) context = new AudioEngine();
      if (context.state !== 'running') context.resume().catch(() => {});
      if (!jingle) {
        const data = Uint8Array.from(atob(soundBytes), c => c.charCodeAt(0));
        jingle = new Promise(resolve => context.decodeAudioData(data.buffer, resolve, () => resolve(null)));
      }
    } catch {}
  }
  function playSound(right) {
    stopSound();
    if (muted) return;
    readyAudio();
    if (!context) return;
    if (right) {
      const generation = soundGeneration;
      if (jingle) jingle.then(buffer => {
        if (!buffer || muted || generation !== soundGeneration) return;
        const source = context.createBufferSource(), gain = context.createGain();
        gain.gain.value = 0.55; source.buffer = buffer;
        source.connect(gain); gain.connect(context.destination); source.start(); playing = source;
      });
    } else {
      const oscillator = context.createOscillator(), gain = context.createGain(), t = context.currentTime;
      oscillator.type = 'sawtooth'; oscillator.frequency.setValueAtTime(128,t); oscillator.frequency.exponentialRampToValueAtTime(86,t+0.17);
      gain.gain.setValueAtTime(0.0001,t); gain.gain.exponentialRampToValueAtTime(0.075,t+0.016); gain.gain.exponentialRampToValueAtTime(0.0001,t+0.19);
      oscillator.connect(gain); gain.connect(context.destination); oscillator.start(t); oscillator.stop(t+0.2); playing = oscillator;
    }
  }
  function selectView(name) {
    ['cover','quiz','end','list'].forEach(view => get(view).hidden = name !== view);
  }
  function setArt(name) { get('illustration').src = name === 'studio' ? get('cover-art').src : illustrations[name]; }
  function reply(index, button) {
    if (answered || button.disabled) return;
    const card = questions[position], right = index === card.key;
    playSound(right);
    const heading = document.createElement('strong');
    if (!right) {
      missed = true; button.disabled = true; button.dataset.result = 'wrong';
      button.querySelector('.pq-letter').textContent = '×';
      heading.className = 'pq-wrong'; heading.textContent = 'Try again.';
      feedback.replaceChildren(heading); return;
    }
    answered = true; if (!missed) firstTry++;
    button.dataset.result = 'right'; button.querySelector('.pq-letter').textContent = '✓';
    Array.from(get('options').children).forEach(choice => choice.disabled = true);
    heading.textContent = 'Correct!';
    feedback.replaceChildren(heading,document.createTextNode(card.why));
    if (card.revealArt) setArt(card.revealArt);
    next.textContent = position === questions.length-1 ? 'See my score' : 'Next card';
    next.hidden = false;
  }
  function renderCard() {
    const card = questions[position];
    missed = false; answered = false; next.hidden = true; feedback.replaceChildren();
    get('chapter').textContent = card.chapter;
    get('count').textContent = 'Card ' + (position+1) + ' of ' + questions.length;
    get('progress').style.width = ((position+1)/questions.length*100) + '%';
    get('question').textContent = card.q; setArt(card.art); get('options').replaceChildren();
    card.a.forEach((answer,i) => {
      const button = document.createElement('button'), letter = document.createElement('span');
      button.type = 'button'; button.className = 'pq-option';
      letter.className = 'pq-letter'; letter.textContent = 'ABC'[i]; letter.setAttribute('aria-hidden','true');
      button.append(letter,document.createTextNode(answer)); button.addEventListener('click',() => reply(i,button));
      get('options').append(button);
    });
    get('question').focus({preventScroll:true});
  }
  function browse() {
    stopSound(); selectView('list');
    if (!get('cards').children.length) questions.forEach((card,i) => {
      const details = document.createElement('details'), summary = document.createElement('summary'), options = document.createElement('ol'), note = document.createElement('p');
      summary.textContent = (i+1) + '. ' + card.q; options.type = 'A';
      card.a.forEach(s => { const li=document.createElement('li'); li.textContent=s; options.append(li); });
      note.textContent = 'Answer ' + 'ABC'[card.key] + '. ' + card.why;
      details.append(summary,options,note); get('cards').append(details);
    });
    get('list').querySelector('h2').focus({preventScroll:true});
  }
  root.querySelectorAll('[data-action="start"]').forEach(button => button.addEventListener('click',() => {
    stopSound(); readyAudio(); position=0; firstTry=0; selectView('quiz'); renderCard();
  }));
  root.querySelectorAll('[data-action="browse"]').forEach(button => button.addEventListener('click',browse));
  next.addEventListener('click',() => {
    if (!answered) return;
    stopSound();
    if (position < questions.length-1) { position++; renderCard(); return; }
    selectView('end'); get('score').textContent = 'You answered ' + firstTry + ' of ' + questions.length + ' correctly on your first try.';
    get('end').querySelector('h2').focus({preventScroll:true});
  });
  soundButton.addEventListener('click',() => {
    muted = !muted; soundButton.setAttribute('aria-pressed', String(!muted)); soundButton.textContent = muted ? 'Sound off' : 'Sound on';
    if (muted) stopSound(); else readyAudio();
  });
})();
